/**
 * 実測がその矩形を返す要素を作る。
 *
 * 4 値をすべて違う値にして、取り違えても落ちるようにする。
 */
function stubbedElement(): Element {
  const element = globalThis.document.createElement("div");
  stubBounds(element, { left: 10, top: 20, width: 30, height: 40 });
  return element;
}

test("描かれている要素の矩形を client 座標の位置と大きさで返す", () => {
  const bounds = CanvasDom.boundsOf(stubbedElement());

  expect(bounds).toEqual({ left: 10, top: 20, width: 30, height: 40 });
});

/**
 * 描かれた大きさをテスト用の値にした `panel`。
 * 掴める範囲と長さの決まり方は実物の node-resize が答える。
 */
function panel(): Element {
  const element = screen.getByTestId("panel");
  stubBounds(element, PanelBounds);
  return element;
}

function grabbed(): string {
  return screen.getByTestId("grabbed").textContent ?? "";
}

function clicked(): string {
  return screen.getByTestId("clicked").textContent ?? "";
}

test("選択中のノードの辺を押すとハンドルを掴む", () => {
  render(
    <NodeResizeHarness
      selection={setupSelection(["panel"])}
      onResize={vi.fn()}
    />,
  );

  pressPointer(panel(), { x: 298, y: 100 });

  expect(grabbed()).toBe("掴んだ");
});

test("指し先が無ければ、DOM を測らずに何も引かない", () => {
  const measured: string[] = [];
  for (const name of ["row", "card"] as const) {
    const element = drawNamed(name, SelectionDistanceTreeBounds[name]);
    const bounds = SelectionDistanceTreeBounds[name];
    stubBoundsEachMeasure(element, () => {
      measured.push(name);
      return bounds;
    });
  }
  const selection = selectionDistanceTree(["row"]);

  const { result } = renderHook(() =>
    useSelectionDistances(selection, Option.none),
  );

  expect(result.current).toEqual(FacingDistances.None);
  expect(measured).toEqual([]);
});

test("⌘ と Alt を一緒に押していると、吸い付かない位置から距離を測り、隙間は出ない", () => {
  renderCanvas({ selection: setupSelection() });
  drawnFollowingFrames();

  // 対照。Alt だけなら左辺が 200 へ寄って `first` に接し、右の `third` までの 64 だけが出る
  carrySecond({ x: -29, y: 30 }, "alt");
  expect(sortedFacingDistanceLabels()).toEqual(["64"]);

  // 同じ位置で ⌘ も押すと吸い付かず、左右 203〜403。左の `first` まで 3、右の `third` まで 61
  movePointer(artboardHandle("second"), { x: -29, y: 30 }, "meta+alt");

  expect(sortedFacingDistanceLabels()).toEqual(["3", "61"]);
  expect(distanceLabels("snap-gap")).toEqual([]);
});

test("⌘ を離して動かし直すと、同じ位置でも再び吸い付く", () => {
  const onRepositionArtboard = vi.fn();
  renderCanvas({ selection: setupSelection(), onRepositionArtboard });
  drawnFollowingFrames();

  // 押している「間」だけ効くことを見るので、1 回のドラッグの中で押していない移動を続ける
  carrySecond({ x: -29, y: 30 }, "meta");
  movePointer(artboardHandle("second"), { x: -29, y: 30 });
  releasePointer(artboardHandle("second"), { x: -29, y: 30 });

  expect(onRepositionArtboard).toHaveBeenCalledWith("second", {
    x: 200,
    y: 30,
  });
});
